package android.content;import java.util.*;public class SharedPreferences {Map<String,Object> map=new HashMap<>();public String getString(String k,String d){Object v=map.get(k);return v==null?d:(String)v;}public int getInt(String k,int d){Object v=map.get(k);return v==null?d:(Integer)v;}public long getLong(String k,long d){Object v=map.get(k);return v==null?d:(Long)v;}public Editor edit(){return new Editor();}public class Editor {Map<String,Object> puts=new HashMap<>();boolean clear;public Editor clear(){clear=true;return this;}public Editor putString(String k,String v){puts.put(k,v);return this;}public Editor putInt(String k,int v){puts.put(k,v);return this;}public Editor putLong(String k,long v){puts.put(k,v);return this;}public boolean commit(){if(clear)map.clear();map.putAll(puts);return true;}}}